/*SQL-ID : isry.couns.constt.etcntabrd.mapper.BbsMomtListMapper.updateChmtBass :  AYA300(수정) - 응용2팀 지원 _ 정원제 */
UPDATE  AYA300
SET     BBSCTT_TTL_NM           =       #{BBSCTT_TTL_NM}
        , LAST_MDFR_ID          =       #{loginId}
        , LAST_MDFCN_DT         =       SYSDATE
WHERE   INDEX_SN                =       #{INDEX_SN}


/*SQL-ID : isry.couns.constt.etcntabrd.mapper.BbsMomtListMapper.deleteChmtBass :  AYA300(삭제) - 응용2팀 지원 _ 정원제 */
UPDATE  AYA300
SET     DEL_YN                  =       'Y'
        , LAST_MDFR_ID          =       #{loginId}
        , LAST_MDFCN_DT         =       SYSDATE
WHERE   INDEX_SN                =       #{INDEX_SN}


/*SQL-ID : isry.couns.constt.etcntabrd.mapper.BbsMomtListMapper.deleteChmtDetail :  AYA310(삭제) - 응용2팀 지원 _ 정원제 */
UPDATE  AYA310
SET     DEL_YN                  =       'Y'
        , LAST_MDFR_ID          =       #{loginId}
        , LAST_MDFCN_DT         =       SYSDATE
WHERE   DTL_INFO_MNG_NO         =       #{DTL_INFO_MNG_NO}
